    try:
        response = session.post(f"{BASE_URL}/login", data={"key": key}, timeout=5)
        if response.status_code == 200:
            data = response.json()
            return float(data.get('balance', 0))
        return 0
    except Exception as e:
        print(f"Balance check error: {e}")
        return 0

def buy_stock():
    try:
        response = session.post(f"{BASE_URL}/buy", data={
            "key": key,
            "stock": "BROOKING"
        }, timeout=5)
        return response.status_code == 200
    except Exception as e:
        print(f"Buy error: {e}")
        return False

def trade_stocks():
    try:
        response = session.post(f"{BASE_URL}/trade", data={
            "key": key,
            "stock": "BROOKING",
            "stock1": "BURPSHARKHAT"
        }, timeout=5)
        return response.status_code == 200
    except Exception as e:
        return False

def get_flag():
    try:
        response = session.post(f"{BASE_URL}/flag", data={"key": key}, timeout=5)
        return response.text
    except Exception as e:
        print(f"Flag error: {e}")
        return None

